import {mergeGoogleConfig,matchesGoogleAccount} from './oauth-config.mjs';
import {uploadToComputer} from './computer.mjs';
import {normalizeRecord,sourceFingerprint,resolveRevisions,searchRecords,buildStyleBrief} from './core.mjs';
import {DriveLibrary,DRIVE_FILE_SCOPE,DRIVE_READONLY_SCOPE} from './drive.mjs';
import {kindOf,mimeOf,smallFileHash,sampleFile,dataUrl,sha256} from './media.mjs';

const $=id=>document.getElementById(id);
const S={googleExpectedEmail:'',driveTransfers:new Map(),drivePolling:false,files:new Map(),computerUrl:'',db:null,records:[],drafts:[],dirty:new Set(),settings:{clientId:'',folderId:'',includeExternal:false},token:'',scopes:'',drive:null,bridge:null,clients:[],busy:false,active:null,jobs:new Map(),previewUrls:new Map(),tab:'upload',brief:null};
const now=()=>new Date().toISOString();
const uuid=()=>crypto.randomUUID();
const array=value=>Array.isArray(value)?value:[];
const lines=value=>String(value||'').split(/\n/).map(x=>x.trim()).filter(Boolean);
const words=value=>String(value||'').split(/[,，、\n]/).map(x=>x.trim()).filter(Boolean);
const size=n=>n>=1024*1024*1024?(n/(1024**3)).toFixed(1)+' GB':n>=1024*1024?(n/(1024**2)).toFixed(1)+' MB':Math.max(1,Math.round(n/1024))+' KB';
function node(tag,text='',className=''){const e=document.createElement(tag);if(text!==null)e.textContent=text;if(className)e.className=className;return e;}
function toast(message,error=false){$('toast').textContent=message;$('toast').classList.toggle('error',error);$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,error?8500:4500);}
function settingMessage(message,error=false){$('settingsStatus').dataset.userMessage='true';$('settingsStatus').textContent=message;$('settingsStatus').className='inline-status '+(error?'error':S.token?'success':'');}
function tab(name){S.tab=name;for(const id of ['upload','library','settings']){$('view-'+id).hidden=id!==name;$('view-'+id).classList.toggle('active',id===name);}document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===name));if(name==='library')renderLibrary();window.scrollTo({top:0,behavior:'auto'});}
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>tab(b.dataset.tab)));
function dbOpen(){return new Promise((resolve,reject)=>{const r=indexedDB.open('shirley-asset-library',1);r.onupgradeneeded=()=>{for(const [name,key]of Object.entries({records:'revision',drafts:'assetId',blobs:'key',settings:'key',sessions:'key',sync:'revision',jobs:'key'}))if(!r.result.objectStoreNames.contains(name))r.result.createObjectStore(name,{keyPath:key});};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error||Error('此浏览器无法打开本机素材库'));r.onblocked=()=>reject(Error('请关闭其他旧素材库页面后重试'));});}
function dbPut(store,value){return new Promise((resolve,reject)=>{const tx=S.db.transaction(store,'readwrite');tx.objectStore(store).put(value);tx.oncomplete=()=>resolve(value);tx.onerror=()=>reject(tx.error||Error('设备存储空间不足'));tx.onabort=()=>reject(tx.error||Error('设备保存未完成'));});}
function dbGet(store,key){return new Promise((resolve,reject)=>{const r=S.db.transaction(store).objectStore(store).get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function dbAll(store){return new Promise((resolve,reject)=>{const r=S.db.transaction(store).objectStore(store).getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function dbRemove(store,key){return new Promise((resolve,reject)=>{const tx=S.db.transaction(store,'readwrite');tx.objectStore(store).delete(key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
const sessionStore={get:async key=>(await dbGet('sessions',key))?.value,put:async(key,value)=>dbPut('sessions',{key,value}),remove:key=>dbRemove('sessions',key)};
async function saveSettings(){await dbPut('settings',{key:'connection',...S.settings});}
function applySettings(){for(const name of ['clientId','folderId'])$(name).value=S.settings[name]||'';$('includeExternal').checked=!!S.settings.includeExternal;$('currentOrigin').textContent=location.origin;}
function connected(){return!!S.token&&!!S.drive;}
function renderConnection(){renderComputer();const online=navigator.onLine!==false;const c=$('connectionStatus');c.classList.toggle('connected',connected()&&online);c.classList.toggle('offline',!online);$('connectionText').textContent=!online?'离线 · 此设备':connected()?'Google Drive 已连接':S.bridge?.driveTransfer?.available?'Drive 后台已连接':directAvailable()?'电脑素材库已连接':'此设备';$('disconnectDrive').hidden=!connected();$('connectDrive').textContent=connected()?'重新连接':'连接 Google Drive';const pending=S.drafts.some(d=>!d.uploaded);$('uploadCloud').disabled=S.busy||!pending;$('saveLocal').disabled=S.busy||!pending;const nativeLink=$('nativeDriveUpload');if(S.bridge?.driveTransfer?.configured&&!connected()&&!$('settingsStatus').dataset.userMessage)$('settingsStatus').textContent='后台转存已接通；浏览器直连尚未启用（可选）';if(nativeLink){nativeLink.hidden=!S.settings.folderId;nativeLink.className=S.bridge?.driveTransfer?.configured?'button secondary':!S.settings.clientId?'button primary':'text-button';nativeLink.textContent=S.bridge?.driveTransfer?.configured?'查看 Google Drive 文件夹 ↗':!S.settings.clientId?'打开 Google Drive 上传原件 ↗':'先用 Google Drive 上传 ↗';nativeLink.href='https://drive.google.com/drive/folders/'+encodeURIComponent(S.settings.folderId||'');} $('uploadHint').textContent=connected()?'原件保存到你的私有云盘；缩图与抽样帧单独保存，不覆盖原件。':S.bridge?.driveTransfer?.configured?'Drive 后台已接通，点击上方“上传并转存”即可。浏览器直连是可选方式。':'尚未连接 Google Drive。可以先保留草稿，连接后继续上传。';}
function fillScopes(){for(const id of ['uploadScope','libraryScope','detailScope']){const select=$(id),current=select.value;select.replaceChildren(new Option('个人素材','personal'),new Option('通用素材','shared'));for(const c of S.clients)if(c.key&&!['personal','shared'].includes(c.key))select.append(new Option(c.name||c.key,c.key));if([...select.options].some(o=>o.value===current))select.value=current;}}
function currentHeads(){return resolveRevisions(S.records);}
function conflictRecords(c){return array(c.revisions).map(v=>typeof v==='string'?S.records.find(r=>r.revision===v):v).filter(Boolean);}
function headFor(assetId){const heads=currentHeads().heads;return heads.find(r=>r.assetId===assetId)||null;}
function replaceRecord(record){const i=S.records.findIndex(r=>r.revision===record.revision);if(i<0)S.records.push(record);else S.records[i]=record;}
async function restoreMirror(clientScope=$('libraryScope').value){if(!S.bridge)return;const response=await bridgePost('list',{clientScope});for(const raw of response.records||[]){const r=normalizeRecord(raw),old=S.records.find(x=>x.revision===r.revision);if(old&&JSON.stringify(old)!==JSON.stringify(r))throw Error('电脑与设备同版本内容冲突，历史未覆盖');await dbPut('records',r);replaceRecord(r);}renderLibrary();}
async function syncMirror(records=S.records){if(!S.bridge||!records.length)return;for(let i=0;i<records.length;i+=200)await bridgePost('import',{records:records.slice(i,i+200)});}
async function putRecord(raw,{sync=true}={}){const r=normalizeRecord(raw);const old=S.records.find(x=>x.revision===r.revision);if(old&&JSON.stringify(old)!==JSON.stringify(r))throw Error('同一版本出现不同内容，未覆盖本机历史；请核对云端原记录');await dbPut('records',r);replaceRecord(r);if(S.bridge)try{await syncMirror([r]);}catch(error){toast('此设备已保存；电脑镜像稍后同步：'+error.message,true);}if(sync&&r.source.provider==='drive'){S.dirty.add(r.revision);await dbPut('sync',{revision:r.revision,pending:true});if(connected())try{await S.drive.saveRecord(r);S.dirty.delete(r.revision);await dbRemove('sync',r.revision);}catch(error){if(/401|授权|令牌|token/i.test(error.message))expireConnection();toast('此设备已保存；云端版本稍后同步：'+error.message,true);}}renderLibrary();return r;}
async function syncPending(){if(!connected())return;for(const revision of [...S.dirty]){const r=S.records.find(x=>x.revision===revision);if(!r||r.source.provider!=='drive')continue;try{await S.drive.saveRecord(r);S.dirty.delete(revision);await dbRemove('sync',revision);}catch(error){toast('部分版本尚未同步：'+error.message,true);break;}}}
function forkRecord(r,change={}){return{...r,...change,revision:uuid(),parentRevisions:[r.revision],createdAt:now()};}
function rightsFor(basis){return{basis,allowedUses:['internal-reference'],evidenceRef:basis==='pending'?'':'用户于 '+now()+' 在上传页面声明'+(basis==='owned'?'拥有此素材':'已获得使用许可')};}
function displayScope(key){return key==='personal'?'个人素材':key==='shared'?'通用素材':S.clients.find(c=>c.key===key)?.name||'客户素材';}
function badge(text,type=''){return node('span',text,'badge '+type);}
function recordBadges(r,{conflict=false}={}){const items=[];if(conflict)items.push(badge('版本待选择','warning'));const job=[...S.jobs.values()].find(j=>j.assetId===r.assetId&&['queued','running'].includes(j.status));if(job)items.push(badge(job.status==='running'?'分析中':'已排队'));else if(r.analysis?.status==='complete'&&r.analysis.sourceFingerprint===sourceFingerprint(r))items.push(badge('分析已完成','success'));else items.push(badge('待分析','warning'));items.push(badge(r.review?.status==='approved'?'已审核':r.review?.status==='rejected'?'不采用':'待审核',r.review?.status==='approved'?'success':''));if(r.rights?.basis==='pending')items.push(badge('用途待确认'));if(S.dirty.has(r.revision))items.push(badge('版本待同步','warning'));return items;}
function previewKey(record,sample){return record.assetId+':'+sample.id+':'+(sample.fileId||'')+':'+(sample.sha256||sourceFingerprint(record));}
async function previewBlob(record,sample){const key=previewKey(record,sample);let local=await dbGet('blobs',key);if(!local&&sample.sha256){const legacy=await dbGet('blobs',record.assetId+':'+sample.id);if(legacy?.blob&&await sha256(legacy.blob)===sample.sha256)local=legacy;}if(local?.blob){if(sample.sha256&&await sha256(local.blob)!==sample.sha256)throw Error('预览与登记版本不一致，未使用旧画面');return local.blob;}if(sample.fileId&&record.source.provider==='computer'&&S.bridge){const blob=await computerBlob(record,sample);if(sample.sha256&&await sha256(blob)!==sample.sha256)throw Error('电脑预览与登记哈希不符');await dbPut('blobs',{key,blob});return blob;}if(sample.fileId&&connected()){const blob=await S.drive.readBlob(sample.fileId);if(blob.size>5*1024*1024)throw Error('预览过大，请在电脑补充缩图');if(sample.sha256&&await sha256(blob)!==sample.sha256)throw Error('云端预览与登记哈希不符');await dbPut('blobs',{key,blob});return blob;}return null;}
async function imageFor(record,sample){const cacheKey=previewKey(record,sample);if(S.previewUrls.has(cacheKey))return S.previewUrls.get(cacheKey);const blob=await previewBlob(record,sample);if(!blob)return null;const url=URL.createObjectURL(blob);S.previewUrls.set(cacheKey,url);return url;}
const previewObserver=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){previewObserver.unobserve(entry.target);const r=S.records.find(x=>x.revision===entry.target.dataset.revision);const sample=r?.samples?.[0];if(sample)imageFor(r,sample).then(url=>{if(url&&entry.target.isConnected){const image=node('img');image.src=url;image.alt=r.name;image.loading='lazy';entry.target.append(image);}}).catch(()=>{});}}, {rootMargin:'180px'});
function renderLibrary(){if(!S.db)return;const {heads,conflicts,invalid=[]}=currentHeads();const scope=$('libraryScope').value,filter=$('reviewFilter').value;const conflictIds=new Set(conflicts.map(c=>c.assetId));let rows=heads.filter(r=>r.clientScope===scope);if(filter==='conflict')rows=rows.filter(r=>conflictIds.has(r.assetId));else if(filter!=='all')rows=rows.filter(r=>r.review?.status===filter);const query=$('searchInput').value.trim().toLowerCase();if(query)rows=rows.filter(r=>(r.name+' '+array(r.analysis?.result?.tags).join(' ')+' '+array(r.analysis?.result?.observed).map(x=>x.value).join(' ')+' '+array(r.analysis?.result?.inferred).map(x=>x.value).join(' ')).toLowerCase().includes(query));rows.sort((a,b)=>b.createdAt.localeCompare(a.createdAt));$('libraryCount').textContent=rows.length+' 份素材 · '+displayScope(scope);$('libraryCoverage').textContent=connected()?'已连接云盘；刷新可同步其他设备版本':'此设备记录；连接云盘后可同步';$('emptyLibrary').hidden=rows.length>0;$('assetGrid').replaceChildren();previewObserver.disconnect();for(const r of rows.slice(0,120)){const card=node('button',null,'asset-card');card.type='button';const wrap=node('div',r.kind==='video'?'▷':'▧','asset-image-wrap');wrap.dataset.revision=r.revision;wrap.append(node('span',r.kind==='video'?'视频':'照片','asset-kind'));const body=node('div',null,'asset-body');body.append(node('h3',r.name));const status=node('div',null,'status-row');status.append(...recordBadges(r,{conflict:conflictIds.has(r.assetId)}));const transfer=S.driveTransfers.get(r.assetId);if(transfer)body.append(node('p',driveTransferText(transfer),'field-note'));body.append(status,node('p',array(r.analysis?.result?.tags).slice(0,3).join(' · ')||'留待观察与整理','asset-tags'));card.append(wrap,body);card.addEventListener('click',()=>openDetail(r.revision));$('assetGrid').append(card);previewObserver.observe(wrap);}$('conflictNotice').hidden=!conflicts.some(c=>conflictRecords(c).some(r=>r.clientScope===scope))&&!invalid.length;if(!$('conflictNotice').hidden)$('conflictNotice').textContent=conflicts.some(c=>conflictRecords(c).some(r=>r.clientScope===scope))?'有素材同时产生了不同版本。旧版本均保留，请打开素材选择；冲突解决前不会用于风格参考。':'部分云端记录格式不兼容，暂未用于参考。';}
function updateDraft(d){const i=S.drafts.findIndex(x=>x.assetId===d.assetId);if(i<0)S.drafts.push(d);else S.drafts[i]=d;return dbPut('drafts',d);}
function draftProgress(id,progress){const d=S.drafts.find(x=>x.assetId===id);if(d){d.percent=progress.percent||0;if(progress.phase==='complete')d.originalUploaded=true;d.note=progress.phase==='complete'?'原件已上传，正在保存分析资料':'正在上传 '+Math.round(d.percent)+'%';renderQueue();}}
function renderQueue(){$('queueSection').hidden=!S.drafts.length;$('queueCount').textContent=S.drafts.filter(d=>d.uploaded).length+' / '+S.drafts.length+' 已保存';$('uploadQueue').replaceChildren();for(const d of S.drafts){const item=node('article',null,'queue-item');const preview=node('div',d.kind==='video'?'▷':'▧','queue-preview');const body=node('div');body.append(node('div',d.name,'queue-name'),node('p',size(d.bytes)+' · '+displayScope(d.clientScope)+'\n'+(d.note||'待上传'),'queue-detail'));if(d.percent>0&&!d.uploaded){const p=node('progress',null,'queue-progress');p.max=100;p.value=d.percent;body.append(p);}const transfer=S.driveTransfers.get(d.assetId);if(transfer){body.append(node('p',driveTransferText(transfer),'field-note'));if(transfer.receipt)appendDriveLink(body,transfer);if(['failed','uncertain'].includes(transfer.status)){const retry=node('button','重试转存 Drive','text-button');retry.addEventListener('click',async()=>{try{await bridgePost('drive-retry',{assetId:d.assetId,clientScope:d.clientScope});await refreshDriveTransfers();}catch(e){toast(e.message,true);}});body.append(retry);}}const action=node('div',null,'queue-actions');if(!S.busy&&!d.uploaded){const b=node('button',d.error?'重试':'继续上传','button secondary');b.addEventListener('click',()=>d.target==='computer'?uploadComputerDrafts([d.assetId]):uploadDrafts([d.assetId]));action.append(b);}else action.append(badge(d.uploaded?(transfer?.status==='complete'?'Drive 已保存':d.target==='computer'&&S.bridge?.driveTransfer?.configured?'电脑已接收':'已保存'):S.busy?'处理中':'已保留',d.uploaded?'success':''));item.append(preview,body,action);$('uploadQueue').append(item);}renderConnection();}
async function chooseFiles(files){if(!S.db){toast('此设备存储尚未就绪',true);return;}for(const file of files){let kind;try{kind=kindOf(file);}catch(error){toast(file.name+'：'+error.message,true);continue;}const resumed=S.drafts.find(x=>!x.uploaded&&x.name===file.name&&x.bytes===file.size&&x.lastModified===(file.lastModified||0)&&x.mimeType===mimeOf(file));const d=resumed||{assetId:uuid(),requestId:uuid(),name:file.name,bytes:file.size,lastModified:file.lastModified||0,mimeType:mimeOf(file),kind,clientScope:$('uploadScope').value,rights:rightsFor($('uploadRights').value),createdAt:now(),note:'已在此设备保留，准备生成预览',uploaded:false,prepared:false};try{S.files.set(d.assetId,file);try{await dbPut('blobs',{key:'source:'+d.assetId,blob:file});}catch{d.note='当前页面可上传；刷新后需重新选择原文件继续';}await updateDraft(d);renderQueue();await prepareDraft(d,file);}catch(error){toast('未能完整保留 '+file.name+'：'+error.message,true);}}$('fileInput').value='';renderQueue();$('queueSection').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'nearest'});}
async function prepareDraft(d,file){if(d.prepared)return d;d.note='正在生成预览';renderQueue();const sampled=await sampleFile(file,{onProgress:p=>{d.note='正在提取画面 '+p.current+'/'+p.total;renderQueue();}});d.samples=[];for(const sample of sampled.samples){await dbPut('blobs',{key:d.assetId+':'+sample.id,blob:sample.blob});d.samples.push({id:sample.id,timeMs:sample.timeMs,sha256:sample.sha256});}d.limits=sampled.limits;d.prepared=true;d.note=sampled.samples.length?'预览已备好 · 可上传原件':'原件已保留 · 预览待电脑补充';await updateDraft(d);renderQueue();return d;}
$('fileInput').addEventListener('change',e=>chooseFiles([...e.target.files]));for(const name of ['dragenter','dragover'])$('dropzone').addEventListener(name,e=>{e.preventDefault();$('dropzone').classList.add('dragging');});for(const name of ['dragleave','drop'])$('dropzone').addEventListener(name,e=>{e.preventDefault();$('dropzone').classList.remove('dragging');});$('dropzone').addEventListener('drop',e=>chooseFiles([...e.dataTransfer.files]));
async function localSave(){if(S.busy)return;S.busy=true;renderQueue();try{for(const d of S.drafts.filter(d=>!d.uploaded)){if(headFor(d.assetId))continue;const file=(await dbGet('blobs','source:'+d.assetId))?.blob;if(!file)continue;const hash=await smallFileHash(file);if(!hash){d.note='大文件草稿已保留，连接云盘后继续上传；暂不运行分析';await updateDraft(d);continue;}const r=await putRecord({assetId:d.assetId,revision:uuid(),parentRevisions:[],name:d.name,bytes:d.bytes,mimeType:d.mimeType,kind:d.kind,clientScope:d.clientScope,createdAt:d.createdAt,source:{provider:'local',sha256:hash},rights:d.rights,review:{status:'pending'},samples:d.samples||[],analysis:{status:'pending',specVersion:1}});d.note='此设备已入库；可继续上传云端';await updateDraft(d);if($('analyzeAfterUpload').checked&&S.bridge?.analyzer?.available&&r.samples.length)void analyzeRecord(r).catch(error=>toast(error.message,true));}toast('草稿与可分析素材已保存在此设备');}catch(error){toast(error.message,true);}finally{S.busy=false;renderQueue();renderLibrary();}}
$('saveLocal').addEventListener('click',localSave);
async function uploadDrafts(ids){if(S.busy)return;if(!connected()){toast('先连接 Google Drive，再继续上传');tab('settings');return;}S.busy=true;renderQueue();try{await S.drive.ensureFolder();await syncPending();for(const d of S.drafts.filter(d=>!d.uploaded&&(!ids||ids.includes(d.assetId)))){try{const existingCloud=headFor(d.assetId);if(d.originalUploaded&&existingCloud?.source.provider==='drive'&&!S.dirty.has(existingCloud.revision)){d.uploaded=true;d.note='原件与资料均已云端保存';await updateDraft(d);continue;}const file=(await dbGet('blobs','source:'+d.assetId))?.blob;if(!file)throw Error('此设备找不到原件，请重新选择文件');const uploadFile=new File([file],d.name,{type:d.mimeType,lastModified:d.lastModified||0});if(!d.prepared)await prepareDraft(d,uploadFile);d.note='正在上传原件';d.error=null;await updateDraft(d);renderQueue();const original=await S.drive.upload(uploadFile,{assetId:d.assetId,requestId:d.requestId,name:d.name,mimeType:d.mimeType,onProgress:p=>draftProgress(d.assetId,p)});const samples=[];for(const sample of d.samples||[]){const blob=(await dbGet('blobs',d.assetId+':'+sample.id))?.blob;if(!blob)continue;const m=await S.drive.uploadSample(blob,{assetId:d.assetId,sampleId:sample.id});samples.push({...sample,fileId:m.fileId});}const existing=headFor(d.assetId);const r=await putRecord({...(existing||{}),assetId:d.assetId,revision:uuid(),parentRevisions:existing?[existing.revision]:[],name:d.name,bytes:d.bytes,mimeType:original.mimeType||d.mimeType,kind:d.kind,clientScope:d.clientScope,createdAt:now(),source:{provider:'drive',fileId:original.fileId,md5Checksum:original.md5Checksum||undefined,modifiedTime:original.modifiedTime||undefined},rights:existing?.rights||d.rights,review:{status:'pending'},samples,analysis:{status:'pending',specVersion:1}});d.originalUploaded=true;d.uploaded=!S.dirty.has(r.revision);d.percent=100;d.note=!d.uploaded?'原件已上传；资料待同步，请保持此设备缓存':samples.length?'已云端入库 · 待分析与审核':'原件已云端入库 · 预览待电脑补充';await updateDraft(d);renderQueue();void refreshDriveTransfers();if($('analyzeAfterUpload').checked&&S.bridge?.analyzer?.available&&samples.length)void analyzeRecord(r).catch(error=>toast(error.message,true));}catch(error){d.error=error.message;d.note='已保留进度：'+error.message;await updateDraft(d);if(/401|授权|令牌|token/i.test(error.message))expireConnection();renderQueue();break;}}}catch(error){toast(error.message,true);}finally{S.busy=false;renderQueue();renderLibrary();}}
$('uploadCloud').addEventListener('click',()=>uploadDrafts());
function expireConnection(){S.token='';S.scopes='';S.drive=null;settingMessage('授权已失效，请重新连接。此设备资料与上传进度仍然保留。',true);renderConnection();}
let gisReady;
async function loadGIS(){if(window.google?.accounts?.oauth2)return;if(!gisReady)gisReady=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.async=true;script.defer=true;script.onload=()=>window.google?.accounts?.oauth2?resolve():reject(Error('Google 授权组件未就绪'));script.onerror=()=>{gisReady=null;reject(Error('无法读取 Google 授权页面，请检查网络后重试'));};document.head.append(script);});await gisReady;}
function readSettings(){const clientId=$('clientId').value.trim(),folderId=$('folderId').value.trim();if(clientId&&!/^[a-zA-Z0-9._-]+\.apps\.googleusercontent\.com$/.test(clientId))throw Error('请填写 Google 网页客户端 ID，不要填写 API 密钥');if(folderId&&!/^[a-zA-Z0-9_-]{5,200}$/.test(folderId))throw Error('请只填写文件夹 ID，不要粘贴整段网址');return{clientId,folderId,includeExternal:$('includeExternal').checked};}
$('settingsForm').addEventListener('submit',async e=>{e.preventDefault();try{const next=readSettings(),changed=next.clientId!==S.settings.clientId||next.folderId!==S.settings.folderId||next.includeExternal!==S.settings.includeExternal;S.settings=next;await saveSettings();if(changed&&S.token)expireConnection();renderConnection();settingMessage('设置已保存在此设备。'+(changed?'请连接 Google Drive 以确认权限。':''));toast('设置已保存');}catch(error){settingMessage(error.message,true);}});
function preparedGoogleTokenClient(){const signature=JSON.stringify([S.settings.clientId,S.settings.includeExternal,S.googleExpectedEmail]);if(S.googleTokenClient?.signature===signature)return S.googleTokenClient.client;const scopes=[DRIVE_FILE_SCOPE,...(S.settings.includeExternal?[DRIVE_READONLY_SCOPE]:[])].join(' ');const client=google.accounts.oauth2.initTokenClient({client_id:S.settings.clientId,login_hint:S.googleExpectedEmail||undefined,scope:scopes,include_granted_scopes:true,callback:async response=>{try{if(response.error||!response.access_token)throw Error(response.error_description||'Google 未完成授权');if(!google.accounts.oauth2.hasGrantedAllScopes(response,DRIVE_FILE_SCOPE))throw Error('尚未取得本应用素材文件访问权限');let verified=false;const candidateToken=response.access_token;const candidateDrive=new DriveLibrary({token:()=>verified?S.token:candidateToken,folderId:S.settings.folderId,sessionStore});const account=await candidateDrive.account();if(!matchesGoogleAccount(account,S.googleExpectedEmail))throw Error('请使用指定的素材库账号 '+S.googleExpectedEmail+' 完成授权，当前账号未用于读取文件夹或同步素材。');const ownerId=account.user?.permissionId||account.user?.emailAddress;if(!ownerId)throw Error('未能核实云盘账号，未开始同步');const owner=await dbGet('settings','owner');if(owner&&owner.id!==ownerId)throw Error('此设备保留了另一个 Google 账号的素材。请切回原账号，或用独立浏览器连接；现有缓存不会清除，也不会同步给这个账号。');const folder=await candidateDrive.ensureFolder();const folderId=typeof folder==='string'?folder:folder?.id||folder?.fileId||candidateDrive.folderId;if(folderId&&!S.settings.folderId){S.settings.folderId=folderId;$('folderId').value=folderId;await saveSettings();}if(!owner)await dbPut('settings',{key:'owner',id:ownerId,email:account.user?.emailAddress||''});verified=true;S.token=candidateToken;S.scopes=response.scope||'';S.drive=candidateDrive;clearTimeout(S.tokenTimer);S.tokenTimer=setTimeout(expireConnection,Math.max(30,(Number(response.expires_in)||3600)-60)*1000);settingMessage('Google Drive 已连接。'+(S.settings.includeExternal&&!hasReadonly()?' 其他云端文件的只读权限尚未授予。':''));renderConnection();await syncPending();await refreshCloud();toast('已连接你的 Google Drive');}catch(error){expireConnection();settingMessage(error.message+(error.status===403&&S.settings.folderId?'。若文件夹由其他助手或Drive创建，请开启“发现其他云端文件”后重新授权，或留空由网页新建专用目录。':''),true);}finally{$('connectDrive').disabled=false;}},error_callback:error=>{$('connectDrive').disabled=false;settingMessage(error.type==='popup_failed_to_open'?'Safari 未能打开 Google 登录窗口。请在 Safari 设置中允许弹出式窗口，再重新连接。':error.type==='popup_closed'?'Google 登录窗口在授权完成前关闭了（popup_closed）。请重新连接；若 Google 页面有错误码，请保留该错误码。':'Google 授权未完成（'+String(error.type||'unknown')+'），原件与设置已保留。',true);}});S.googleTokenClient={signature,client};return client;}
$('connectDrive').addEventListener('click',()=>{try{S.settings=readSettings();if(!S.settings.clientId)throw Error('先填写自己的 Google OAuth 网页客户端 ID');if(!window.google?.accounts?.oauth2){void loadGIS().then(()=>{if(S.settings.clientId)preparedGoogleTokenClient();}).catch(error=>settingMessage(error.message,true));settingMessage('登录组件正在载入，请稍后再次点击连接');return;}void saveSettings().catch(error=>settingMessage(error.message,true));$('connectDrive').disabled=true;settingMessage('正在打开 Google 授权页面…');const client=preparedGoogleTokenClient();client.requestAccessToken({prompt:S.token?'':'consent'});}catch(error){$('connectDrive').disabled=false;settingMessage(error.message,true);}});
$('disconnectDrive').addEventListener('click',()=>{const token=S.token;clearTimeout(S.tokenTimer);S.token='';S.scopes='';S.drive=null;if(token&&window.google?.accounts?.oauth2)google.accounts.oauth2.revoke(token,()=>{});settingMessage('已断开 Google Drive；此设备的素材、缩图和进度仍保留。');renderConnection();toast('已断开，设备资料未清除');});
function hasReadonly(){return S.scopes.split(/\s+/).includes(DRIVE_READONLY_SCOPE);}
async function refreshCloud(){if(!connected()){if(directAvailable()){try{await restoreMirror();toast('已读取电脑素材库');}catch(e){toast(e.message,true);}return;}toast('连接 Google Drive 后可同步其他设备素材');return;}$('refreshCloud').disabled=true;try{const list=await S.drive.listRecords();let count=0,invalid=0;for(const entry of list){try{const r=normalizeRecord(entry.record);const old=S.records.find(x=>x.revision===r.revision);if(old&&JSON.stringify(old)!==JSON.stringify(r))throw Error('同一云端版本内容不同，未覆盖本机历史');await dbPut('records',r);replaceRecord(r);count++;}catch{invalid++;}}await syncPending();await syncMirror();renderLibrary();toast('已读取 '+count+' 个云端版本'+(invalid?'；'+invalid+' 个不兼容记录未采用':''));}catch(error){if(/401|授权|令牌|token/i.test(error.message))expireConnection();toast('云端刷新未完成：'+error.message,true);}finally{$('refreshCloud').disabled=false;}}
$('refreshCloud').addEventListener('click',refreshCloud);
$('discoverExternal').addEventListener('click',async()=>{if(!connected()){toast('请先连接 Google Drive');tab('settings');return;}if(!S.settings.includeExternal||!hasReadonly()){toast('先在设置中开启“发现其他云端文件”，再重新授权');tab('settings');return;}$('discoverExternal').disabled=true;$('externalList').replaceChildren();try{const result=await S.drive.listExternal();const files=array(result.files);$('externalHint').textContent='本次发现 '+files.length+' 份可读取素材。只代表当前授权可见范围，不代表完整云盘。';for(const file of files.slice(0,100)){const row=node('div',null,'external-row'),info=node('div');info.append(node('strong',file.name||'未命名素材'),node('small',(file.mimeType||'')+' · '+size(Number(file.size)||0)));const b=node('button','登记到素材库','button secondary');b.addEventListener('click',async()=>{b.disabled=true;try{const existing=S.records.find(r=>r.source.provider==='drive'&&r.source.fileId===file.id);if(existing){toast('这份原件已经登记');return;}const r=await putRecord({assetId:uuid(),revision:uuid(),parentRevisions:[],name:file.name||'云端素材',mimeType:file.mimeType,bytes:Number(file.size)||0,kind:file.mimeType?.startsWith('video/')?'video':'image',clientScope:$('libraryScope').value,createdAt:now(),source:{provider:'drive',fileId:file.id,md5Checksum:file.md5Checksum||undefined,modifiedTime:file.modifiedTime||undefined},rights:{basis:'pending',allowedUses:['internal-reference'],evidenceRef:''},review:{status:'pending'},samples:[],analysis:{status:'pending',specVersion:1}});b.textContent='已登记';toast('已登记原件位置；电脑可继续补充预览和分析。');renderLibrary();if($('analyzeAfterUpload').checked&&S.bridge?.analyzer?.available)void analyzeRecord(r).catch(error=>toast(error.message,true));}catch(error){b.disabled=false;toast(error.message,true);}});row.append(info,b);$('externalList').append(row);}if(!files.length)$('externalList').append(node('p','没有发现当前授权可读取的新素材。','field-note'));}catch(error){toast('发现未完成：'+error.message,true);}finally{$('discoverExternal').disabled=false;}});
function directAvailable(){return!!S.bridge?.computerUpload?.available;}
async function computerRaw(path,params,blob){if(!S.bridge?.token)throw Error('电脑通道尚未连接');const q=new URLSearchParams(Object.entries(params).map(([k,v])=>[k,String(v)]));const r=await fetch('/api/library/'+path+'?'+q,{method:'POST',headers:{'X-Hub-Token':S.bridge.token,'Content-Type':'application/octet-stream'},body:blob,signal:AbortSignal.timeout(45000)});if(!(r.headers.get('content-type')||'').includes('application/json'))throw Error('连接已过期，请刷新页面完成邮箱验证，再继续上传');const out=await r.json();if(!r.ok)throw Error(out.error||'电脑未接收此分块');return out;}
async function computerBlob(record,sample){if(!S.bridge?.token)throw Error('请通过电脑素材库入口读取');const body={assetId:record.assetId,clientScope:record.clientScope,sha256:sample?.sha256||record.source.sha256,...(sample?{sampleId:sample.fileId}:{})};const r=await fetch('/api/library/computer-file',{method:'POST',headers:{'Content-Type':'application/json','X-Hub-Token':S.bridge.token},body:JSON.stringify(body)});if(!r.ok||(r.headers.get('content-type')||'').includes('text/html'))throw Error('原件读取失败，请刷新并重新完成邮箱验证');return await r.blob();}
function renderComputer(){if($('backendDriveStatus'))$('backendDriveStatus').textContent=S.bridge?.driveTransfer?.configured?(S.bridge.driveTransfer.message+'。下方为可选的浏览器直连设置，后台转存无需填写。'):'通过私有上传入口可检查后台 Drive 连接。';const pending=S.drafts.some(d=>!d.uploaded),available=directAvailable();$('uploadComputer').disabled=S.busy||(available?!pending:!S.computerUrl);$('uploadComputer').textContent=available?(S.bridge?.driveTransfer?.configured?'上传并转存 Google Drive':'上传到电脑素材库'):'进入私有上传页面';$('computerEntry').hidden=available||!S.computerUrl;if(S.computerUrl)$('computerEntry').href=S.computerUrl;$('computerHint').textContent=available?(S.bridge?.driveTransfer?.configured?'无需 Google Cloud 配置。经家中电脑自动转存私人 Drive，回读核验后显示成功。转存使用现有 Codex 订阅，原件经官方文件服务中转。单件512 MiB以内；较大文件保留在电脑并标明待转存。请保持电脑开机联网。':'无需 Google 配置。文件直接保存到家里的电脑，请保持电脑开机联网。'):S.computerUrl?'先进入私有上传页面，完成邮箱验证，再选择照片或视频。':'当前电脑连接未就绪。可以先保存草稿；Google Drive 选项仍可使用。';}
async function loadComputerEntry(){try{const r=await fetch('./config.json',{cache:'no-store'});if(r.ok){const c=await r.json();const u=c.computerUploadUrl&&new URL(c.computerUploadUrl);if(u&&u.protocol==='https:'&&/^[a-z0-9-]+\.trycloudflare\.com$/.test(u.hostname))S.computerUrl=u.origin+'/library/';}}catch{}renderComputer();}
async function uploadComputerDrafts(ids){if(!directAvailable()){if(S.computerUrl)location.assign(S.computerUrl);else toast('电脑入口尚未连接，请稍后刷新',true);return;}if(S.busy)return;S.busy=true;renderQueue();try{for(const d of S.drafts.filter(d=>!d.uploaded&&(!ids||ids.includes(d.assetId)))){try{d.target='computer';d.error=null;const stored=(await dbGet('blobs','source:'+d.assetId))?.blob;const chosen=S.files.get(d.assetId)||stored;if(!chosen)throw Error('请重新选择同一个原文件，已确认的上传进度会继续保留');const file=new File([chosen],d.name,{type:d.mimeType,lastModified:d.lastModified||0});if(!d.prepared)await prepareDraft(d,file);d.note='正在分块上传到电脑';await updateDraft(d);let record=await uploadToComputer(file,d,{post:bridgePost,raw:computerRaw,sha256,onProgress:p=>{d.percent=p;d.note=p>=100?'字节已收齐，正在校验并入库':'正在上传到电脑 '+Math.round(p)+'%';renderQueue();}});const head=headFor(d.assetId);if(head?.source.provider==='computer'&&head.source.sha256===record.source.sha256)record=head;else record=await putRecord(record,{sync:false});const samples=[];for(const sample of d.samples||[]){const blob=(await dbGet('blobs',d.assetId+':'+sample.id))?.blob;if(!blob)continue;const saved=await computerRaw('upload-sample',{requestId:d.requestId,clientScope:d.clientScope,sampleId:sample.id,timeMs:sample.timeMs,sha256:sample.sha256},blob);samples.push(saved);}if(samples.length&&JSON.stringify(record.samples)!==JSON.stringify(samples))record=await putRecord(forkRecord(record,{samples,analysis:{status:'pending',specVersion:1},review:{status:'pending'}}),{sync:false});d.uploaded=true;d.originalUploaded=true;d.percent=100;d.note=samples.length?'原件与预览已保存到电脑 · 待分析和审核':'原件已保存到电脑 · 预览待补充';await updateDraft(d);renderQueue();if($('analyzeAfterUpload').checked&&S.bridge?.analyzer?.available&&samples.length)void analyzeRecord(record).catch(e=>toast(e.message,true));}catch(error){d.error=error.message;d.note='进度已保留：'+error.message;await updateDraft(d);toast(error.message,true);renderQueue();break;}}}finally{S.busy=false;renderQueue();renderLibrary();}}
$('uploadComputer').addEventListener('click',()=>uploadComputerDrafts());

function driveTransferText(t){return ({queued:'电脑已接收 · 等待转存 Drive',uploading:'正在转存 Google Drive',verifying:'Drive 已收到 · 正在回读核对原件',complete:'已保存到私人 Google Drive · 原件校验一致',uncertain:'转存结果待核对 · 原件与进度保留',failed:'Drive 转存未完成：'+(t.error||'请重试'),large_file_pending:t.error||'超大文件已保留，等待Drive转存'})[t.status]||'Drive 状态待核对';}
function appendDriveLink(parent,t){try{const u=new URL(t.receipt.url);if(u.protocol!=='https:'||u.hostname!=='drive.google.com')return;const a=node('a','在 Google Drive 查看原件 ↗','text-button');a.href=u.href;a.target='_blank';a.rel='noopener noreferrer';parent.append(a);}catch{}}
async function refreshDriveTransfers(){if(!S.bridge||S.drivePolling)return;S.drivePolling=true;try{const scopes=new Set([$ ('uploadScope').value,$ ('libraryScope').value]);for(const clientScope of scopes){const result=await bridgePost('drive-status',{clientScope});S.bridge.driveTransfer=result.connection;for(const t of result.transfers||[])S.driveTransfers.set(t.assetId,t);}renderQueue();renderLibrary();if(S.active)renderDetailActions(S.active);}catch{}finally{S.drivePolling=false;}}
setInterval(()=>{if(!document.hidden)void refreshDriveTransfers();},6000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)void refreshDriveTransfers();});
async function bridgePost(path,body){if(!S.bridge?.token)throw Error('当前没有电脑分析通道；云端原件仍可保存');const response=await fetch('/api/library/'+path,{method:'POST',headers:{'Content-Type':'application/json','X-Hub-Token':S.bridge.token},credentials:'same-origin',body:JSON.stringify(body)});let result;try{result=await response.json();}catch{throw Error('电脑分析通道暂时不可读');}if(!response.ok)throw Error(result.error||'电脑未接受此请求');return result;}
async function prepareCloudRecord(record){if(!connected()||!S.bridge)throw Error('请在电脑工作台连接 Google Drive 后补充预览');toast('电脑正在读取云端原件并生成少量预览，原件保持不变');const prepared=await bridgePost('prepare-cloud',{record,accessToken:S.token});const samples=[];for(const sample of prepared.samples||[]){const m=/^data:image\/(jpeg|png);base64,([A-Za-z0-9+/=]+)$/.exec(sample.dataUrl||'');if(!m)throw Error('电脑返回的预览编码无效');const decoded=atob(m[2]);const blob=new Blob([Uint8Array.from(decoded,c=>c.charCodeAt(0))],{type:'image/'+m[1]});if(await sha256(blob)!==sample.sha256)throw Error('电脑返回的预览哈希不符');await dbPut('blobs',{key:record.assetId+':'+sample.id,blob});const cloud=await S.drive.uploadSample(blob,{assetId:record.assetId,sampleId:sample.id});samples.push({id:sample.id,timeMs:sample.timeMs,sha256:sample.sha256,fileId:cloud.fileId});}if(!samples.length)throw Error('当前解码器未取得可读画面，原件仍保留');const next=forkRecord(record,{source:prepared.source,bytes:prepared.info.bytes||record.bytes,mimeType:prepared.info.mimeType||record.mimeType,samples,analysis:{status:'pending',specVersion:1},review:{status:'pending'}});const saved=await putRecord(next);if(S.active?.assetId===saved.assetId)await openDetail(saved.revision);return saved;}
async function analyzeRecord(r,{retry=false}={}){if(!S.bridge?.analyzer?.available){toast('已保留原件。请在电脑工作台打开素材库，接着完成分析。');return;}if(r.source.provider==='drive'&&connected()){const current=await S.drive.fileInfo(r.source.fileId);const changed=(current.md5Checksum&&current.md5Checksum!==r.source.md5Checksum)||(current.modifiedTime&&current.modifiedTime!==r.source.modifiedTime)||Number(current.size)!==r.bytes;if(changed||!r.samples.length)r=await prepareCloudRecord(r);}if(r.analysis?.status==='complete'&&r.analysis.sourceFingerprint===sourceFingerprint(r)&&!retry){toast('这份原件已有有效分析，可直接审核。');return;}if(!r.samples.length){toast('此格式尚无可读画面，待电脑补充预览后再分析。');return;}const active=[...S.jobs.values()].find(j=>j.assetId===r.assetId&&['queued','running'].includes(j.status));if(active){toast('这份素材已在分析队列中');return;}const samples=[];for(const sample of r.samples.slice(0,6)){const blob=await previewBlob(r,sample);if(!blob)throw Error('缺少预览，请连接云盘读取抽样画面');samples.push({id:sample.id,timeMs:sample.timeMs,dataUrl:await dataUrl(blob)});}await bridgePost('import',{records:[r]});const response=await bridgePost('analyze',{record:r,samples,...(retry?{retry:true}:{})});const job=response.job;if(!job?.id)throw Error('电脑没有返回可回查的分析任务');const local={...job,key:job.id,assetId:r.assetId,revision:r.revision,clientScope:r.clientScope,sourceFingerprint:sourceFingerprint(r)};S.jobs.set(job.id,local);await dbPut('jobs',local);renderLibrary();if(S.active?.assetId===r.assetId)renderDetailActions(r);toast(job.status==='complete'?'找到已有分析，正在保存结果':'已交给电脑分析，原件不会被覆盖');void pollJob(local).catch(error=>toast('分析状态读取暂停：'+error.message,true));}
async function pollJob(local){if(local.polling)return;local.polling=true;try{for(let count=0;count<480;count++){if(!S.bridge)return;let job=local;if(!['complete','failed','unavailable'].includes(job.status)){const response=await bridgePost('job',{id:local.id,clientScope:local.clientScope});job=response.job;if(!job)throw Error('未找到这份分析任务');Object.assign(local,job);S.jobs.set(local.id,local);await dbPut('jobs',{...local,polling:false});}if(job.status==='complete'){const source=S.records.find(r=>r.revision===local.revision);if(!source)throw Error('原件版本已改变，请重新检查');if(job.sourceFingerprint&&job.sourceFingerprint!==sourceFingerprint(source))throw Error('分析与当前原件版本不匹配，结果未采用');const prior=S.records.find(r=>r.parentRevisions?.includes(source.revision)&&r.analysis?.status==='complete'&&r.analysis.sourceFingerprint===sourceFingerprint(source));if(!prior){const completed=forkRecord(source,{analysis:{status:'complete',sourceFingerprint:sourceFingerprint(source),specVersion:1,result:job.result},review:{status:'pending'}});const saved=await putRecord(completed);if(S.active?.assetId===saved.assetId)await openDetail(saved.revision);}local.status='complete';await dbPut('jobs',{...local,polling:false});renderLibrary();toast('分析已保存，请审核标签与适用方向。');return;}if(['failed','unavailable'].includes(job.status)){renderLibrary();if(S.active?.assetId===local.assetId)renderDetailActions(S.active);toast(job.status==='unavailable'?'电脑分析尚未就绪，原件与样本已保留。':'分析未完成：'+(job.error||'可在详情中明确重试'),true);return;}renderLibrary();await new Promise(resolve=>setTimeout(resolve,2500));}toast('分析仍在电脑队列中。可以稍后打开本页继续查看。');}finally{local.polling=false;}}
async function bootstrap(){let controller=new AbortController(),timer=setTimeout(()=>controller.abort(),7000);try{const response=await fetch('/api/library/bootstrap',{cache:'no-store',credentials:'same-origin',signal:controller.signal});if(!response.ok)return;const data=await response.json();if(!data.local||!data.token)return;S.bridge=data;S.clients=array(data.clients);fillScopes();}catch{}finally{clearTimeout(timer);const available=!!S.bridge?.analyzer?.available;$('analyzerStatus').textContent=available?'电脑分析通道已就绪；新素材可按需分析。':'云端上传可独立使用。电脑通道未连接时，素材会保留为待分析。';$('settingsAnalyzer').textContent=available?'当前电脑可处理缩图与有限抽样帧；分析结果保存后仍需人工审核。':'当前页面未连接电脑分析通道。先将原件收进云盘，之后在电脑工作台继续分析。';}}
$('libraryScope').addEventListener('change',()=>restoreMirror().catch(error=>toast('电脑索引未读完：'+error.message,true)));
$('searchInput').addEventListener('input',()=>{$('briefPanel').hidden=true;renderLibrary();});for(const id of ['libraryScope','reviewFilter'])$(id).addEventListener('change',()=>{$('briefPanel').hidden=true;renderLibrary();});
function buildBrief(){try{const brief=buildStyleBrief(S.records,{prompt:$('searchInput').value.trim(),clientScope:$('libraryScope').value,use:$('searchUse').value});S.brief=brief;$('briefPanel').hidden=false;$('briefText').textContent=brief.text||'尚未找到当前用途可采用的参考。请先补齐分析、审核及许可。';$('briefRefs').replaceChildren(...array(brief.refs).map(r=>node('span',r.name||r.assetId||'参考素材')));$('copyBrief').disabled=brief.status!=='ready';$('downloadBrief').disabled=brief.status!=='ready';$('briefPanel').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'nearest'});}catch(error){toast(error.message,true);}}
$('searchButton').addEventListener('click',buildBrief);$('searchInput').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();buildBrief();}});$('closeBrief').addEventListener('click',()=>$('briefPanel').hidden=true);
async function copyText(text,fallback){try{if(!navigator.clipboard?.writeText)throw Error('Clipboard unavailable');await navigator.clipboard.writeText(text);toast('已复制');}catch{fallback.hidden=false;fallback.value=text;fallback.focus();fallback.select();toast('请长按或全选下面文字复制');}}
$('copyBrief').addEventListener('click',()=>copyText(S.brief?.text||'',$('copyFallback')));$('downloadBrief').addEventListener('click',()=>{if(!S.brief?.text)return;const url=URL.createObjectURL(new Blob([S.brief.text],{type:'text/plain;charset=utf-8'}));const a=node('a');a.href=url;a.download='Shirley-风格制作简报-'+new Date().toISOString().slice(0,10)+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);});
document.querySelectorAll('[data-copy-url]').forEach(button=>button.addEventListener('click',()=>copyText(button.dataset.copyUrl,$('urlFallback'))));
function timeLabel(ms){if(ms==null)return'原图预览';const seconds=ms/1000;return Math.floor(seconds/60).toString().padStart(2,'0')+':'+(seconds%60).toFixed(1).padStart(4,'0');}
async function openDetail(revision){const r=S.records.find(x=>x.revision===revision);if(!r)return;S.active=r;$('detailTitle').textContent=r.name;$('detailType').textContent=(r.kind==='video'?'视频':'照片')+' · '+displayScope(r.clientScope);$('detailPreview').replaceChildren();for(const sample of r.samples){const figure=node('figure'),caption=node('figcaption',timeLabel(sample.timeMs));figure.append(caption);$('detailPreview').append(figure);imageFor(r,sample).then(url=>{if(!url)return;const img=node('img');img.src=url;img.alt=r.name+' · '+timeLabel(sample.timeMs);figure.prepend(img);}).catch(()=>{});}if(!r.samples.length)$('detailPreview').append(node('p','原件已保留，当前还没有可读预览。'));$('detailStatus').replaceChildren(...recordBadges(r));const result=r.analysis?.result||{};$('detailTags').value=array(result.tags).join('，');$('detailObserved').value=array(result.observed).map(x=>x.value).join('\n');$('detailUses').value=array(result.inferred).map(x=>x.value).join('\n');$('detailPairings').value=array(result.pairings).map(x=>typeof x==='string'?x:x.value||x.element||'').join('\n');$('detailAvoid').value=array(result.avoid).join('\n');$('detailPalette').value=array(result.palette).join(', ');$('detailScope').value=r.clientScope;$('detailRights').value=r.rights.basis;$('detailRightsRef').value=r.rights.evidenceRef||'';document.querySelectorAll('[name=allowedUse]').forEach(input=>input.checked=r.rights.allowedUses.includes(input.value));$('detailReview').value=r.review.status;$('feedbackNote').value='';$('detailLimits').textContent=[...array(result.limits),...(r.kind==='video'?['只依据已保存的抽样帧；未读取的音轨与片段不作判断。']:[]),'AI 标签和搭配建议仍须人工核对。'].join('\n');renderDetailActions(r);renderFeedback(r);renderVersions(r);if(!$('assetDialog').open)$('assetDialog').showModal();}
function renderDetailActions(r){const actions=$('detailActions');actions.replaceChildren();const transfer=S.driveTransfers.get(r.assetId);if(transfer?.receipt)appendDriveLink(actions,transfer);const analyze=node('button',S.bridge?.analyzer?.available?'分析这份素材':'待电脑分析','button primary');analyze.disabled=!S.bridge?.analyzer?.available||!r.samples.length;analyze.addEventListener('click',async()=>{analyze.disabled=true;try{await analyzeRecord(r);}catch(error){toast(error.message,true);}finally{analyze.disabled=false;}});actions.append(analyze);if(r.source.provider==='drive'&&S.bridge&&connected()){const prepare=node('button','从云端补充预览','button secondary');prepare.addEventListener('click',async()=>{prepare.disabled=true;try{await prepareCloudRecord(r);toast('预览已保存，可以分析并审核');}catch(error){toast(error.message,true);}finally{prepare.disabled=false;}});actions.append(prepare);}const failed=[...S.jobs.values()].find(j=>j.assetId===r.assetId&&['failed','unavailable'].includes(j.status));if(failed){const retry=node('button','重新运行失败的分析','button secondary');retry.addEventListener('click',()=>analyzeRecord(r,{retry:true}).catch(error=>toast(error.message,true)));actions.append(retry);}if(r.source.provider==='drive'){const link=node('a','在云盘查看原件 ↗','button secondary');link.href='https://drive.google.com/file/d/'+encodeURIComponent(r.source.fileId)+'/view';link.target='_blank';link.rel='noopener noreferrer';actions.append(link);}else if(r.source.provider==='computer'){const download=node('button','下载电脑原件','button secondary');download.addEventListener('click',async()=>{try{const blob=await computerBlob(r);const url=URL.createObjectURL(blob),a=node('a');a.href=url;a.download=r.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}catch(error){toast(error.message,true);}});actions.append(download);}else{const original=node('button','查看此设备原件','button secondary');original.addEventListener('click',async()=>{const blob=(await dbGet('blobs','source:'+r.assetId))?.blob;if(!blob){toast('此设备找不到原件',true);return;}const url=URL.createObjectURL(blob);window.open(url,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(url),60000);});actions.append(original);}}
function renderVersions(r){const conflict=currentHeads().conflicts.find(c=>c.assetId===r.assetId),box=$('detailVersions');box.replaceChildren();if(!conflict)return;const panel=node('div',null,'version-box');panel.append(node('strong','不同设备产生了多个版本，历史均已保留。'),node('p','选择一版查看，再明确采用；解决前不会用于参考。'));for(const version of conflictRecords(conflict)){const row=node('div',null,'version-option'),label=node('span',new Date(version.createdAt).toLocaleString()+' · '+array(version.analysis?.result?.tags).slice(0,2).join('/'));const inspect=node('button','查看这一版','button secondary');inspect.addEventListener('click',()=>openDetail(version.revision));row.append(label,inspect);panel.append(row);}const adopt=node('button','采用当前这一版，保留所有历史','button secondary');adopt.addEventListener('click',async()=>{try{const saved=await putRecord({...r,revision:uuid(),parentRevisions:conflictRecords(conflict).map(x=>x.revision),createdAt:now()});toast('已建立采用版本，其他历史仍保留');await openDetail(saved.revision);}catch(error){toast(error.message,true);}});panel.append(adopt);box.append(panel);}
function renderFeedback(r){$('feedbackHistory').replaceChildren(...array(r.feedback).slice(-5).reverse().map(f=>node('div',(f.verdict==='keep'?'喜欢这个方向':f.verdict==='avoid'?'以后避开':'需要调整')+' · '+new Date(f.at).toLocaleDateString()+'\n'+(f.note||'未填写原因'),'feedback-entry')));}
$('closeDetail').addEventListener('click',()=>$('assetDialog').close());$('assetDialog').addEventListener('click',e=>{if(e.target===$('assetDialog')){const rect=$('assetDialog').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)$('assetDialog').close();}});
$('detailForm').addEventListener('submit',async e=>{e.preventDefault();const r=S.active;if(!r)return;try{const palette=words($('detailPalette').value);if(palette.some(x=>!/^#[0-9a-f]{6}$/i.test(x)))throw Error('色彩请使用六位色号，例如 #EADCC9');const observed=lines($('detailObserved').value),result={observed:observed.map(value=>({field:'visual',value,evidenceIds:r.samples.map(s=>s.id)})),inferred:lines($('detailUses').value).map(value=>({field:'use',value,reason:'人工填写的用途建议'})),tags:words($('detailTags').value),palette,pairings:lines($('detailPairings').value),avoid:lines($('detailAvoid').value),limits:array(r.analysis?.result?.limits)};if((observed.length||result.tags.length||result.inferred.length)&&!r.samples.length)throw Error('先补充可读预览，再记录基于画面的观察；原件继续保留');const previous=r.analysis?.result;if(previous){if(JSON.stringify(observed)===JSON.stringify(previous.observed.map(x=>x.value)))result.observed=previous.observed;if(JSON.stringify(lines($('detailUses').value))===JSON.stringify(previous.inferred.map(x=>x.value)))result.inferred=previous.inferred;}const analysis=observed.length?{...r.analysis,status:'complete',sourceFingerprint:sourceFingerprint(r),specVersion:1,result}:r.analysis;const rights={basis:$('detailRights').value,allowedUses:[...document.querySelectorAll('[name=allowedUse]:checked')].map(x=>x.value),evidenceRef:$('detailRightsRef').value.trim()};const clientScope=$('detailScope').value;if(clientScope!==r.clientScope)throw Error('此处保留原来的客户归属。需迁移时请由项目总控核对，避免跨客户复用。');const saved=await putRecord(forkRecord(r,{analysis,rights,review:{status:$('detailReview').value,at:now(),note:'用户在素材详情确认'}}));await openDetail(saved.revision);toast('新版本已保存');}catch(error){toast(error.message,true);}});
async function feedback(verdict){const r=S.active;if(!r)return;try{const saved=await putRecord(forkRecord(r,{feedback:[...array(r.feedback),{id:uuid(),verdict,note:$('feedbackNote').value.trim(),at:now()}]}));await openDetail(saved.revision);toast('偏好已记录，仍保留原分析与版本');}catch(error){toast(error.message,true);}}
$('feedbackKeep').addEventListener('click',()=>feedback('keep'));$('feedbackAvoid').addEventListener('click',()=>feedback('avoid'));
for(const event of ['online','offline'])window.addEventListener(event,()=>{renderConnection();if(event==='online')toast('网络已恢复，可以继续上传');});
window.addEventListener('beforeunload',()=>{for(const url of S.previewUrls.values())URL.revokeObjectURL(url);});
async function init(){try{S.db=await dbOpen();const [records,drafts,settings,sync,jobs]=await Promise.all([dbAll('records'),dbAll('drafts'),dbGet('settings','connection'),dbAll('sync'),dbAll('jobs')]);S.records=records.map(r=>{try{return normalizeRecord(r);}catch{return null;}}).filter(Boolean);S.drafts=drafts.map(d=>({...d,note:d.uploaded?d.note:'此设备已保留进度，可继续上传'}));if(settings)S.settings={clientId:settings.clientId||'',folderId:settings.folderId||'',includeExternal:!!settings.includeExternal};try{const response=await fetch('./config.json',{cache:'no-store'});if(response.ok){const merged=mergeGoogleConfig(S.settings,await response.json());S.settings=merged.settings;S.googleExpectedEmail=merged.expectedEmail;await saveSettings();}}catch{}const incoming=new URLSearchParams(location.hash.slice(1)).get('folder');if(incoming&&/^[A-Za-z0-9_-]{5,200}$/.test(incoming)&&!S.settings.folderId){S.settings.folderId=incoming;await saveSettings();history.replaceState(null,'',location.pathname+location.search);}S.dirty=new Set(sync.filter(x=>x.pending).map(x=>x.revision));for(const j of jobs)S.jobs.set(j.key,{...j,polling:false});applySettings();renderQueue();renderLibrary();await bootstrap();await loadComputerEntry();void refreshDriveTransfers();if(S.bridge)try{await restoreMirror();await syncMirror();}catch(error){toast('电脑镜像尚未同步：'+error.message,true);}void loadGIS().then(()=>{if(S.settings.clientId)preparedGoogleTokenClient();}).catch(()=>{});$('studioLink').href=S.bridge?'https://kamegui0910-eng.github.io/shirley-creative-studio/':'../';$('hubLink').hidden=!S.bridge;$('footerStudioLink').href=$('studioLink').href;if(S.bridge){$('hubLink').href=S.bridge.limitedGateway?'/library/':'/';if(S.bridge.limitedGateway)$('hubLink').textContent='返回素材库首页';}for(const j of S.jobs.values())if(S.bridge&&['queued','running'].includes(j.status))void pollJob(j).catch(()=>{});if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(()=>{});}catch(error){$('analyzerStatus').textContent='此设备存储不可用。请使用 Safari 或 Chrome 的普通浏览模式。';toast('素材库未就绪：'+error.message,true);}}
void init();
